declare(strict_types=1);$pageTitle='Narrative Manager';$topNavSection='roleplay';$BODY_CLASS='hub-page';require __DIR__.'/ui_bootstrap.php';$rows=$uiRepository->rows('narratives');$installations=$uiRepository->rows('installations');$profiles=array_merge($uiRepository->rows('characters'),$uiRepository->rows('player'));$playthroughs=$uiRepository->rows('playthroughs');include __DIR__.'/tmpl/head.html';if(!$embedded)include __DIR__.'/tmpl/navbar.php';?>
<main class="almsivi-page<?php echo $embedded?' embedded':''; ?>"><header class="almsivi-page-header"><div><h1>Narratives</h1><p>Create scoped narrator, diary, and summary records included in roleplay context.</p></div><span class="almsivi-badge"><?php echo count($rows); ?> narratives</span></header><?php if(isset($_GET['status'])): ?><div class="almsivi-status">Narrative saved.</div><?php endif; ?><section class="almsivi-card"><h2>Create narrative</h2><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/narratives"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><div class="almsivi-form-grid"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Profile<select name="profile_id"><?php foreach($profiles as$row): ?><option value="<?php echo almsivi_ui_h($row['profile_id']); ?>"><?php echo almsivi_ui_h($row['name']); ?></option><?php endforeach; ?></select></label><label>Playthrough<select name="playthrough_id"><?php foreach($playthroughs as$row): ?><option value="<?php echo almsivi_ui_h($row['playthrough_id']); ?>"><?php echo almsivi_ui_h($row['playthrough']); ?></option><?php endforeach; ?></select></label><label>Kind<select name="kind"><option value="narrator">Narrator</option><option value="diary">Diary</option><option value="summary">Summary</option></select></label><label>Title<input name="title" required></label><label class="wide">Narrative<textarea name="content" required></textarea></label><label>Provenance<input name="provenance" value="management" required></label></div><div class="almsivi-actions"><button type="submit">Create Narrative</button></div></form></section><section class="almsivi-grid"><?php foreach($rows as$row): ?><article class="almsivi-card"><h2><?php echo almsivi_ui_h($row['title']); ?></h2><p><?php echo nl2br(almsivi_ui_h($row['content'])); ?></p><details><summary>Edit narrative</summary><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/narrative-revise"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="narrative_id" value="<?php echo almsivi_ui_h($row['narrative_id']); ?>"><label>Kind<select name="kind"><?php foreach(['narrator','diary','summary']as$kind): ?><option<?php echo $row['kind']===$kind?' selected':''; ?>><?php echo almsivi_ui_h($kind); ?></option><?php endforeach; ?></select></label><label>Title<input name="title" required value="<?php echo almsivi_ui_h($row['title']); ?>"></label><label>Narrative<textarea name="content" required><?php echo almsivi_ui_h($row['content']); ?></textarea></label><label>Provenance<input name="provenance" value="management edit" required></label><div class="almsivi-actions"><button type="submit">Save Narrative</button></div></form></details><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/narrative-delete" data-confirm="Delete this narrative?"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="narrative_id" value="<?php echo almsivi_ui_h($row['narrative_id']); ?>"><button class="danger" type="submit">Delete</button></form></article><?php endforeach; ?><?php if($rows===[]): ?><article class="almsivi-card almsivi-empty">No narratives exist yet.</article><?php endif; ?></section></main><?php include __DIR__.'/tmpl/footer.html'; ?>
